use near_workspaces::{Account,Contract,Worker,network::Sandbox,types::{NearToken,Gas}};
use serde_json::{json,Value};
const U:u128=1_000_000_000_000_000_000_000;const C:u128=U/100;const F:u128=5*U;
async fn call(a:&Account,c:&Contract,m:&str,args:Value,d:u128)->near_workspaces::result::ExecutionFinalResult {a.call(c.id(),m).args_json(args).deposit(NearToken::from_yoctonear(d)).gas(Gas::from_tgas(150)).transact().await.unwrap()}
fn ok(r:near_workspaces::result::ExecutionFinalResult)->Value {r.into_result().unwrap().json().unwrap_or(Value::Null)}
fn reject(r:near_workspaces::result::ExecutionFinalResult,why:&str){assert!(r.is_failure(),"expected rejection {why}; got {r:?}");assert!(format!("{r:?}").contains(why),"{r:?}");}
async fn read(c:&Contract,m:&str,args:Value)->Value {c.view(m).args_json(args).await.unwrap().json().unwrap()}
async fn setup()->(Worker<Sandbox>,Contract,Account,Account,Account){let w=near_workspaces::sandbox().await.unwrap();let c=w.dev_deploy(&std::fs::read(concat!(env!("CARGO_MANIFEST_DIR"),"/../contract/target/near/kotoba_book.wasm")).unwrap()).await.unwrap();ok(call(c.as_account(),&c,"new",json!({"wasm_url":"https://test.fastfs.io/pinned.wasm","wasm_hash":"b46b08da60dcd4d4970a0712beb0e1b33aab6e332646de4e090974419a7b2314","challenge_window_ns":900_000_000_000u64}),0).await);let now=w.view_block().await.unwrap().timestamp();ok(call(c.as_account(),&c,"create_market",json!({"id":"powell-inflation","event":"What will Powell say?","source_url":"https://www.federalreserve.gov/mediacenter/files/FOMCpresconf20261209.pdf","phrase":"inflation","threshold":1,"close_ns":now+120_000_000_000u64,"deadline_ns":now+86_400_000_000_000u64,"b":100}),70*U).await);let a=w.dev_create_account().await.unwrap();let b=w.dev_create_account().await.unwrap();let d=w.dev_create_account().await.unwrap();(w,c,a,b,d)}
async fn mint(a:&Account,c:&Contract,q:u32){ok(call(a,c,"mint_pairs",json!({"id":"powell-inflation","quantity":q}),q as u128*U+F).await);}
async fn order(a:&Account,c:&Contract,yes:bool,buy:bool,p:u32,q:u32,kind:&str)->Value {ok(call(a,c,"place_order",json!({"id":"powell-inflation","yes":yes,"buy":buy,"price":p,"quantity":q,"kind":kind}),F+if buy{p as u128*q as u128*C}else{0}).await)}
async fn bal(c:&Contract,a:&Account,yes:bool)->u64 {read(c,"balance_of",json!({"id":"powell-inflation","account":a.id(),"yes":yes})).await.as_u64().unwrap()}
async fn cash(c:&Contract,a:&Account)->u128 {read(c,"cash_balance",json!({"account":a.id()})).await.as_str().unwrap().parse().unwrap()}
#[tokio::test]
async fn price_time_priority_partial_fills_and_both_outcomes(){let(_w,c,a,b,t)=setup().await;mint(&a,&c,20).await;mint(&b,&c,20).await;order(&a,&c,true,false,60,3,"limit").await;let first=order(&b,&c,true,false,55,2,"limit").await;let second=order(&a,&c,true,false,55,3,"limit").await;let fill=order(&t,&c,true,true,70,4,"limit").await;assert_eq!(fill["remaining"],0);let h=read(&c,"trade_history",json!({"id":"powell-inflation"})).await;assert_eq!(h[0]["maker_order"],first["order_id"]);assert_eq!(h[1]["maker_order"],second["order_id"]);assert_eq!(h[0]["price"],55);assert_eq!(h[1]["quantity"],2);assert_eq!(bal(&c,&t,true).await,4);assert_eq!(cash(&c,&t).await,60*C);assert_eq!(cash(&c,&a).await,110*C);assert_eq!(cash(&c,&b).await,110*C);let book=read(&c,"get_book",json!({"id":"powell-inflation","yes":true})).await;assert_eq!(book["asks"][0]["remaining"],1);assert_eq!(book["asks"][1]["price"],60);order(&a,&c,false,false,20,5,"limit").await;order(&t,&c,false,true,30,2,"limit").await;assert_eq!(bal(&c,&t,false).await,2);assert_eq!(bal(&c,&t,true).await,4);let snap=read(&c,"snapshot",json!({"account":t.id()})).await;assert_eq!(snap["held"]["powell-inflation:YES"],4);assert_eq!(snap["held"]["powell-inflation:NO"],2);assert_eq!(snap["history"]["powell-inflation"].as_array().unwrap().len(),3);assert_eq!(snap["markets"].as_array().unwrap().len(),1);}
#[tokio::test]
async fn sell_cancel_escrow_and_withdraw(){let(_w,c,a,b,_)=setup().await;mint(&b,&c,10).await;order(&a,&c,true,true,45,3,"limit").await;let sell=order(&b,&c,true,false,40,5,"limit").await;assert_eq!(sell["remaining"],2);assert_eq!(bal(&c,&b,true).await,5);assert_eq!(bal(&c,&a,true).await,3);assert_eq!(cash(&c,&b).await,135*C);reject(call(&a,&c,"cancel_order",json!({"order_id":sell["order_id"]}),1).await,"ERR_ORDER_OWNER");ok(call(&b,&c,"cancel_order",json!({"order_id":sell["order_id"]}),1).await);assert_eq!(bal(&c,&b,true).await,7);reject(call(&b,&c,"cancel_order",json!({"order_id":sell["order_id"]}),1).await,"ERR_ORDER_CLOSED");let bid=order(&a,&c,false,true,25,4,"limit").await;let before=cash(&c,&a).await;ok(call(&a,&c,"cancel_order",json!({"order_id":bid["order_id"]}),1).await);assert_eq!(cash(&c,&a).await,before+100*C);let amount=cash(&c,&b).await;let result=ok(call(&b,&c,"withdraw",json!({"amount":amount.to_string()}),1).await);assert_eq!(result,true);assert_eq!(cash(&c,&b).await,0);}
#[tokio::test]
async fn market_ioc_refunds_and_integer_cent_rounding(){let(_w,c,a,b,_)=setup().await;mint(&a,&c,10).await;order(&a,&c,true,false,1,1,"limit").await;order(&a,&c,true,false,50,1,"limit").await;let o=order(&b,&c,true,true,60,5,"market").await;assert_eq!(o["remaining"],0);assert_eq!(o["cancelled"],true);assert_eq!(bal(&c,&b,true).await,2);assert_eq!(cash(&c,&b).await,(300-51)*C);assert_eq!(cash(&c,&a).await,51*C);let h=read(&c,"trade_history",json!({"id":"powell-inflation"})).await;assert_eq!(h.as_array().unwrap().len(),2);let before=cash(&c,&b).await;order(&b,&c,true,true,99,1,"market").await;assert_eq!(cash(&c,&b).await,before+99*C);let before=bal(&c,&b,true).await;order(&b,&c,true,false,1,1,"market").await;assert_eq!(bal(&c,&b,true).await,before);ok(call(&a,&c,"redeem_pairs",json!({"id":"powell-inflation","quantity":2}),1).await);assert_eq!(cash(&c,&a).await,51*C+2*U);}
#[tokio::test]
async fn attacks_rollback_overselling_callbacks_and_closed_markets(){let(w,c,a,b,_)=setup().await;mint(&a,&c,5).await;let before=cash(&c,&b).await;for(price,quantity,err)in[(0,1,"ERR_PRICE"),(100,1,"ERR_PRICE"),(50,0,"ERR_QUANTITY"),(50,100001,"ERR_QUANTITY")]{reject(call(&b,&c,"place_order",json!({"id":"powell-inflation","yes":true,"buy":true,"price":price,"quantity":quantity,"kind":"limit"}),F).await,err);}reject(call(&b,&c,"place_order",json!({"id":"powell-inflation","yes":true,"buy":false,"price":50,"quantity":1,"kind":"limit"}),F).await,"ERR_INSUFFICIENT_SHARES");assert_eq!(cash(&c,&b).await,before);reject(call(&b,&c,"place_order",json!({"id":"powell-inflation","yes":true,"buy":true,"price":50,"quantity":1,"kind":"limit"}),F).await,"ERR_CASH");reject(call(&b,&c,"on_book_withdraw",json!({"owner":b.id(),"amount":"1"}),0).await,"private");reject(call(&b,&c,"withdraw",json!({"amount":"1"}),1).await,"ERR_CASH");let ask=order(&a,&c,true,false,50,5,"limit").await;order(&b,&c,true,true,50,5,"limit").await;order(&b,&c,true,true,50,1,"market").await;assert_eq!(bal(&c,&b,true).await,5);reject(call(&a,&c,"cancel_order",json!({"order_id":ask["order_id"]}),1).await,"ERR_ORDER_CLOSED");let own=order(&b,&c,true,false,20,1,"limit").await;let self_order=order(&b,&c,true,true,30,1,"market").await;assert_eq!(self_order["cancelled"],true);assert_eq!(read(&c,"trade_history",json!({"id":"powell-inflation"})).await.as_array().unwrap().len(),1);let close=read(&c,"get_market",json!({"id":"powell-inflation"})).await["close_ns"].as_u64().unwrap();while w.view_block().await.unwrap().timestamp()<close {w.fast_forward(1500).await.unwrap();}reject(call(&a,&c,"place_order",json!({"id":"powell-inflation","yes":false,"buy":true,"price":50,"quantity":1,"kind":"limit"}),F+50*C).await,"ERR_CLOSED");ok(call(&b,&c,"cancel_order",json!({"order_id":own["order_id"]}),1).await);}
